<template><section class="dependency-page">
  <header><div><div class="eyebrow">{{ contextLabel }}</div><h1>Dependency explorer</h1><p>Proven infrastructure path from Gardener to physical capacity</p></div><div class="segments"><button v-for="tab in tabs" :key="tab" :class="{active:view===tab}" @click="view=tab">{{ tab }}</button></div></header>
  <v-alert v-if="error" type="error" variant="tonal">{{ error }}</v-alert><v-skeleton-loader v-else-if="loading" type="heading,card"/>
  <EvidenceGraph v-else-if="graph&&rootKey&&view==='Topology'" :graph="graph" :root-key="rootKey"/>
  <section v-else-if="graph&&view==='Inventory'" class="data-panel"><div class="data-heading"><strong>Resource inventory</strong><span>{{ graph.resources.length }} resources in bounded traversal</span></div><div v-for="resource in graph.resources" :key="resource.key" class="data-row"><span>{{ resource.provenance.kind }}</span><strong>{{ resource.provenance.name }}</strong><small>{{ resource.provenance.sourceId }}</small><em>{{ resource.health||resource.state||'unknown' }}</em></div></section>
  <section v-else-if="graph&&view==='Evidence'" class="data-panel"><div class="data-heading"><strong>Relationship evidence</strong><span>{{ graph.relations.length }} directed relationships</span></div><div v-for="relation in graph.relations" :key="relation.from+relation.to" class="data-row"><span>{{ relation.type }}</span><strong>{{ relation.evidence }}</strong><small>{{ relation.fieldPath }}</small><em>{{ relation.confidence }}</em></div></section>
  <div v-else class="empty">No dependency evidence is available for this resource.</div>
</section></template>
<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { useRoute } from 'vue-router'
import { sreApi,type SreGraph } from '@/api/sre'
import EvidenceGraph from '@/components/sre/EvidenceGraph.vue'
const route=useRoute(),graph=ref<SreGraph|null>(null),loading=ref(true),error=ref<string|null>(null),view=ref('Topology'),tabs=['Topology','Inventory','Evidence'],rootKey=computed(()=>graph.value?.resources[0]?.key||'')
const contextLabel=computed(()=>{const root=graph.value?.resources[0];return root?`${root.provenance.kind.toUpperCase()} / ${root.provenance.namespace||root.provenance.sourceId} / ${root.provenance.name}`:'DEPENDENCY / WDF4'})
onMounted(async()=>{try{graph.value=(await sreApi.graph(String(route.params.id))).data}catch(cause){error.value=cause instanceof Error?cause.message:'Dependencies unavailable'}finally{loading.value=false}})
</script>
<style scoped>.dependency-page{max-width:1520px;margin:0 auto;padding:28px 28px 52px}.dependency-page>header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:20px}.eyebrow{color:#9cabff;font-size:11px;font-weight:750;letter-spacing:.12em}.dependency-page h1{font-size:27px;margin:8px 0 5px}.dependency-page header p{margin:0;color:var(--ic-text-muted);font-size:13px}.segments{display:flex;border:1px solid var(--ic-border);border-radius:7px;overflow:hidden}.segments button{border:0;border-right:1px solid var(--ic-border);background:transparent;color:var(--ic-text);padding:8px 14px;font-size:13px}.segments button:last-child{border:0}.segments .active{background:#9cabff;color:#12151d}.empty,.data-panel{border:1px solid var(--ic-border);border-radius:8px;background:var(--ic-surface)}.empty{padding:24px;color:var(--ic-text-muted);font-size:12px}.data-heading{display:flex;justify-content:space-between;padding:14px 16px;border-bottom:1px solid var(--ic-border);font-size:13px}.data-heading span{color:var(--ic-text-muted);font-size:11px}.data-row{display:grid;grid-template-columns:140px 1fr 1.4fr 100px;gap:16px;align-items:center;padding:11px 16px;border-bottom:1px solid var(--ic-border);font-size:12px}.data-row span,.data-row small{color:var(--ic-text-muted)}.data-row em{color:#9cabff;font-style:normal;text-align:right}@media(max-width:760px){.dependency-page{padding:22px 14px}.dependency-page>header{display:block}.segments{margin-top:16px;width:max-content}.data-row{grid-template-columns:1fr}.data-row em{text-align:left}}</style>
